/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-09: readFile options - strict (a read for a reload from storage rejects on a
 *   read error, a missing, empty or invalid file) and noWrite (the backup of an
 *   empty file is read but not copied with readOnly/readOnlyUserDir)
 *   #68: a failed write of the file content rejects; the target is kept and the
 *   temporary file of this call removed
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

const fs = require('fs-extra');
const fspath = require('path');

const log = require("@node-red/util").log;

function parseJSON(data) {
    if (data.charCodeAt(0) === 0xFEFF) {
        data = data.slice(1)
    }
    return JSON.parse(data);
}
function strictError(code, message, cause) {
    const err = new Error(message);
    err.code = code;
    if (cause) {
        err.cause = cause;
    }
    return err;
}

/**
 * Reads and parses a JSON file.
 * @param {string} path
 * @param {string} backupPath - restored when the file is empty
 * @param {*} emptyResponse - the result for a missing, empty or invalid file
 * @param {string} [type]
 * @param {object} [options]
 * @param {boolean} [options.strict] - Z-09: a read for a reload from storage - a read
 *     error, a missing (unless `allowMissing`), empty or invalid file rejects the
 *     promise (codes: the fs code, `empty_file`, `invalid_json`); the backup is not used
 * @param {boolean} [options.allowMissing] - with `strict`: a missing file gives `emptyResponse`
 * @param {boolean} [options.noWrite] - Z-09: no write access (readOnly, readOnlyUserDir) -
 *     the backup of an empty file is read but not copied over the file
 * @return {Promise}
 */
function readFile(path,backupPath,emptyResponse,type,options) {
    options = options || {};
    if (options.strict) {
        return new Promise(function(resolve, reject) {
            fs.readFile(path,'utf8',function(err,data) {
                if (err) {
                    if (err.code === 'ENOENT' && options.allowMissing) {
                        return resolve(emptyResponse);
                    }
                    return reject(err);
                }
                if (data.length === 0) {
                    return reject(strictError("empty_file", "The " + (type || "") + " file is empty: " + path));
                }
                try {
                    resolve(parseJSON(data));
                } catch(parseErr) {
                    reject(strictError("invalid_json", "The " + (type || "") + " file is not valid JSON: " + path, parseErr));
                }
            });
        });
    }
    return new Promise(function(resolve) {
        fs.readFile(path,'utf8',function(err,data) {
            if (!err) {
                if (data.length === 0) {
                    log.warn(log._("storage.localfilesystem.empty",{type:type}));
                    try {
                        var backupStat = fs.statSync(backupPath);
                        if (backupStat.size === 0) {
                            // Empty flows, empty backup - return empty flow
                            return resolve(emptyResponse);
                        }
                        // Empty flows, restore backup
                        log.warn(log._("storage.localfilesystem.restore",{path:backupPath,type:type}));
                        if (options.noWrite) {
                            // Z-09: no write access - the backup is read, not copied
                            return resolve(readFile(backupPath,null,emptyResponse,type,{ noWrite: true }));
                        }
                        fs.copy(backupPath,path,function(backupCopyErr) {
                            if (backupCopyErr) {
                                // Restore backup failed
                                log.warn(log._("storage.localfilesystem.restore-fail",{message:backupCopyErr.toString(),type:type}));
                                resolve([]);
                            } else {
                                // Loop back in to load the restored backup
                                resolve(readFile(path,backupPath,emptyResponse,type));
                            }
                        });
                        return;
                    } catch(backupStatErr) {
                        // Empty flow file, no back-up file
                        return resolve(emptyResponse);
                    }
                }
                try {
                    return resolve(parseJSON(data));
                } catch(parseErr) {
                    log.warn(log._("storage.localfilesystem.invalid",{type:type}));
                    return resolve(emptyResponse);
                }
            } else {
                if (type === 'flow') {
                    log.info(log._("storage.localfilesystem.create",{type:type}));
                }
                resolve(emptyResponse);
            }
        });
    });
}

const writeFileLocks = {}

module.exports = {
    /**
    * Write content to a file using UTF8 encoding.
    * This forces a fsync before completing to ensure
    * the write hits disk.
    */
    writeFile: async function(path,content,backupPath) {
        if (!writeFileLocks[path]) {
            writeFileLocks[path] = Promise.resolve()
        }
        const result = writeFileLocks[path].then(async () => {
            var backupPromise;
            if (backupPath && fs.existsSync(path)) {
                await fs.copy(path,backupPath);
                log.trace(`utils.writeFile - copied ${path} TO ${backupPath}`)
            }

            const dirname = fspath.dirname(path);
            const tempFile = `${path}.$$$`;
            await fs.ensureDir(dirname)

            await new Promise(function(resolve,reject) {
                var stream = fs.createWriteStream(tempFile);
                // #68: true once this call has opened the temporary file - only then is it removed
                var opened = false;
                // #68: "ended" after a successful end, "failed" once fail() has started
                var outcome = null;
                // #68: a failed write of the file content rejects; the target is kept and the
                // temporary file of this call removed. Settles once; no fsync, end or rename after it
                function fail(err) {
                    if (outcome) {
                        return;
                    }
                    outcome = "failed";
                    log.warn(log._("storage.localfilesystem.fsync-fail",{path: tempFile, message: err.toString()}));
                    stream.destroy();
                    var closed = stream.closed ? Promise.resolve() : new Promise(function(done) { stream.once('close', done) });
                    closed.then(function() {
                        if (!opened) {
                            return;
                        }
                        return fs.unlink(tempFile).catch(function(unlinkErr) {
                            log.debug("Removing " + tempFile + " failed: " + unlinkErr.toString());
                        });
                    }).then(function() {
                        reject(err);
                    });
                }
                // Before any other listener of 'open', so that the flag is set when the error comes from one of them
                stream.prependListener('open',function() {
                    opened = true;
                });
                stream.on('open',function(fd) {
                    if (outcome) {
                        return;
                    }
                    try {
                        stream.write(content,'utf8',function(writeErr) {
                            if (writeErr) {
                                return fail(writeErr);
                            }
                            if (outcome) {
                                return;
                            }
                            fs.fsync(fd,function(err) {
                                if (outcome) {
                                    return;
                                }
                                if (err) {
                                    log.warn(log._("storage.localfilesystem.fsync-fail",{path: tempFile, message: err.toString()}));
                                }
                                stream.end(function(endErr) {
                                    if (endErr) {
                                        return fail(endErr);
                                    }
                                    if (outcome) {
                                        return;
                                    }
                                    outcome = "ended";
                                    resolve();
                                });
                            });
                        });
                    } catch(writeErr) {
                        // content that is not a string
                        fail(writeErr);
                    }
                });
                // Kept for the whole life of the stream: before a successful end an error fails
                // the write, after it the error is only logged
                stream.on('error',function(err) {
                    if (outcome === "ended") {
                        log.warn(log._("storage.localfilesystem.fsync-fail",{path: tempFile, message: err.toString()}));
                    } else {
                        fail(err);
                    }
                });
            })
            
            log.trace(`utils.writeFile - written content to ${tempFile}`)
            
            await new Promise(function(resolve,reject) {
                fs.rename(tempFile,path,err => {
                    if (err) {
                        log.warn(log._("storage.localfilesystem.fsync-fail",{path: path, message: err.toString()}));
                        return reject(err);
                    }
                    log.trace(`utils.writeFile - renamed ${tempFile} to ${path}`)
                    resolve();
                })
            })
        })
        writeFileLocks[path] = result.catch(() => {})
        return result
    },
    readFile: readFile,

    parseJSON: parseJSON
}
